/**
 * Held-out learner corpus for the EngFlow grammar checker (blind test set).
 *
 * Written independently of the checker's rules and lexicon, so it can be used
 * to measure recall on real learner errors (WRONG) and the false-positive rate
 * on correct, natural speech (RIGHT).
 *
 * Speaker profile: Korean process engineer, CEFR ~B1, practising spoken English
 * for online meetings, presentations, discussions, small talk, meals, phone
 * calls, negotiation, apologies/problems, site visits and technical talk.
 *
 * WRONG: a realistic spoken sentence (or two short ones) containing exactly ONE
 *   grammar mistake. `right` is the minimal correction; `error` is a kebab-case
 *   label of the mistake type.
 * RIGHT: fully grammatical, natural spoken sentences. `tricky` marks sentences a
 *   naive rule-based checker might wrongly flag, with the reason.
 */

export interface WrongItem { id: string; scene: string; wrong: string; right: string; error: string; }
export interface RightItem { id: string; scene: string; text: string; tricky?: string; }

